CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, pw TEXT NOT NULL, name TEXT NOT NULL, gender TEXT DEFAULT '保密', age INTEGER DEFAULT 25, city TEXT DEFAULT '深圳', bio TEXT DEFAULT '', avatar TEXT DEFAULT '😊', avatar_url TEXT DEFAULT '', tags TEXT DEFAULT '[]', created INTEGER NOT NULL, last_seen INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS likes (liker TEXT NOT NULL, target TEXT NOT NULL, sup INTEGER DEFAULT 0, ts INTEGER NOT NULL, PRIMARY KEY (liker, target));
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, a TEXT NOT NULL, b TEXT NOT NULL, ts INTEGER NOT NULL, pinned_a INTEGER DEFAULT 0, pinned_b INTEGER DEFAULT 0, read_a INTEGER DEFAULT 0, read_b INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS messages (id TEXT PRIMARY KEY, match_id TEXT NOT NULL, sender TEXT NOT NULL, text TEXT DEFAULT '', img TEXT DEFAULT '', recalled INTEGER DEFAULT 0, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_msg_match ON messages (match_id, ts);
CREATE TABLE IF NOT EXISTS blocks (user_id TEXT NOT NULL, blocked TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (user_id, blocked));
CREATE TABLE IF NOT EXISTS posts (id TEXT PRIMARY KEY, uid TEXT NOT NULL, text TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_posts_ts ON posts (ts);
CREATE TABLE IF NOT EXISTS post_likes (post_id TEXT NOT NULL, uid TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (post_id, uid));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, post_id TEXT NOT NULL, uid TEXT NOT NULL, text TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cmts_post ON comments (post_id, ts);
CREATE TABLE IF NOT EXISTS visits (owner TEXT NOT NULL, visitor TEXT NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (owner, visitor));
CREATE TABLE IF NOT EXISTS proposals (id TEXT PRIMARY KEY, from_uid TEXT NOT NULL, to_uid TEXT NOT NULL, ts INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS couples (user_id TEXT PRIMARY KEY, partner TEXT NOT NULL, since INTEGER NOT NULL);
